(function(){
  function a(t){return t.right-t.left}
  function l(t){return t.bottom-t.top}
  function M(t,n,e){return Math.min(e,Math.max(n,t))}
  function s(t,n){return Math.abs(Math.log(t)-Math.log(n))}
  function h(t){
    const n=String(t).split(":");
    if(n.length!==2)return null;
    const e=Number(n[0]);
    const o=Number(n[1]);
    return Number.isFinite(e)&&Number.isFinite(o)&&e>0&&o>0?e/o:null;
  }
  function u(t,n){
    let e=null;
    let o=Infinity;
    for(const r of n||[]){
      if(r==="auto")continue;
      const i=h(r);
      if(!i)continue;
      const c=s(t,i);
      if(c<o){o=c;e=r}
    }
    return e;
  }
  function g(t){
    const{bounds:n}=t;
    const e=a(n);
    const o=l(n);
    return{bounds:{left:n.left,top:n.top,right:n.right,bottom:n.bottom},ratioKey:u(e/o,t.ratios||[]),w:e,h:o};
  }
  function P(t){
    const{docBounds:d,selectionBounds:sel,ratios:r}=t;
    const docW=a(d);
    const docH=l(d);
    const hasAuto=Array.isArray(r)&&r.includes("auto");
    const concrete=(r||[]).filter(k=>k!=="auto");
    if(!sel){
      const docR=docW/docH;
      const nearest=u(docR,concrete);
      const nearestVal=nearest?h(nearest):null;
      // Use "auto" when model supports it and doc ratio doesn't closely match a bucket (< 2%)
      let chosenKey=nearest;
      if(hasAuto&&(!nearestVal||s(docR,nearestVal)>0.02)){
        chosenKey="auto";
      }
      return{
        bounds:{left:0,top:0,right:docW,bottom:docH},
        ratioKey:chosenKey,
        concreteRatioKey:nearest,
        w:docW,
        h:docH,
        contextExpanded:false,
        selectionRelBounds:null
      };
    }
    const selLeft=M(Math.floor(sel.left),0,Math.max(0,docW-2));
    const selTop=M(Math.floor(sel.top),0,Math.max(0,docH-2));
    const selRight=M(Math.ceil(sel.right),selLeft+2,docW);
    const selBottom=M(Math.ceil(sel.bottom),selTop+2,docH);
    const selW=selRight-selLeft;
    const selH=selBottom-selTop;
    const selCx=(selLeft+selRight)/2;
    const selCy=(selTop+selBottom)/2;

    // Expand context symmetrically (with slight upward bias to capture upper pose & light source)
    const minCtxW=Math.min(docW,Math.max(Math.round(selW*1.65),selW+Math.round(docW*0.14)));
    const minCtxH=Math.min(docH,Math.max(Math.round(selH*1.75),selH+Math.round(docH*0.18)));

    let best=null;
    let bestScore=Infinity;
    for(const rKey of concrete){
      const rVal=h(rKey);
      if(!rVal)continue;
      let cw,ch;
      if(minCtxW/minCtxH<rVal){
        cw=Math.max(minCtxW,Math.round(minCtxH*rVal));
        ch=Math.max(minCtxH,Math.round(cw/rVal));
      }else{
        ch=Math.max(minCtxH,Math.round(minCtxW/rVal));
        cw=Math.max(minCtxW,Math.round(ch*rVal));
      }
      if(cw>docW||ch>docH){
        const k=Math.min(docW/cw,docH/ch);
        cw=Math.floor(cw*k);
        ch=Math.floor(ch*k);
      }
      if(cw<selW||ch<selH)continue;
      const minL=Math.max(0,selRight-cw);
      const maxL=Math.min(docW-cw,selLeft);
      const minT=Math.max(0,selBottom-ch);
      const maxT=Math.min(docH-ch,selTop);
      if(minL>maxL||minT>maxT)continue;

      const cLeft=Math.round(M(selCx-cw/2,minL,maxL));
      // Slight upward bias (0.56 below top edge) captures legs/body above feet cleanly while respecting floor below
      const cTop=Math.round(M(selCy-ch*0.56,minT,maxT));
      const areaFactor=(cw*ch)/Math.max(1,minCtxW*minCtxH);
      const ratioDist=s(rVal,minCtxW/minCtxH);
      const score=areaFactor+ratioDist*1.4;
      if(score<bestScore){
        bestScore=score;
        best={
          bounds:{left:cLeft,top:cTop,right:cLeft+cw,bottom:cTop+ch},
          ratioKey:rKey,
          concreteRatioKey:rKey,
          w:cw,
          h:ch,
          contextExpanded:cw>selW||ch>selH
        };
      }
    }

    if(!best){
      const bw=Math.min(docW,Math.max(selW,Math.round(minCtxW)));
      const bh=Math.min(docH,Math.max(selH,Math.round(minCtxH)));
      const bLeft=Math.round(M(selCx-bw/2,Math.max(0,selRight-bw),Math.min(docW-bw,selLeft)));
      const bTop=Math.round(M(selCy-bh/2,Math.max(0,selBottom-bh),Math.min(docH-bh,selTop)));
      const nearest=u(bw/bh,concrete);
      best={
        bounds:{left:bLeft,top:bTop,right:bLeft+bw,bottom:bTop+bh},
        ratioKey:hasAuto?"auto":nearest,
        concreteRatioKey:nearest,
        w:bw,
        h:bh,
        contextExpanded:bw>selW||bh>selH
      };
    }

    const cb=best.bounds;
    const rw=Math.max(1,cb.right-cb.left);
    const rh=Math.max(1,cb.bottom-cb.top);
    best.selectionRelBounds={
      leftPct:Math.round((selLeft-cb.left)/rw*100),
      topPct:Math.round((selTop-cb.top)/rh*100),
      rightPct:Math.round((selRight-cb.left)/rw*100),
      bottomPct:Math.round((selBottom-cb.top)/rh*100)
    };
    return best;
  }
  function b(t){
    const{placedBounds:n,captureBounds:e}=t;
    const o=t.tolerance??.005;
    const r=a(n);
    const i=l(n);
    const c=a(e);
    const f=l(e);
    const m=r/i;
    const p=c/f;
    const F=Math.max(c/r,f/i);
    return{percent:F*100,ratioMismatch:s(m,p)>Math.log(1+o),placedRatio:m,captureRatio:p};
  }
  function y(t,n){return{dx:(n.left+n.right)/2-(t.left+t.right)/2,dy:(n.top+n.bottom)/2-(t.top+t.bottom)/2}}
  function d(t){
    if(!Array.isArray(t)||t.length<8)return null;
    const n=[t[0],t[2],t[4],t[6]];
    const e=[t[1],t[3],t[5],t[7]];
    if(![...n,...e].every(Number.isFinite))return null;
    return{left:Math.min(...n),top:Math.min(...e),right:Math.max(...n),bottom:Math.max(...e)};
  }
  function w(t){
    const n=Math.min(a(t),l(t));
    return Math.min(M(Math.round(.055*n),3,140),Math.floor(n/8));
  }
  const x=typeof window!=="undefined"?window:globalThis;
  x.nanoBananaGeometry={parseRatio:h,nearestRatioKey:u,planGeneration:g,planContextCapture:P,planPlacement:b,centerDelta:y,boundsFromTransformQuad:d,revealFeatherRadius:w};
})();
